import{_ as a,o as e,c as o,ag as d}from"./chunks/framework.D7Pdja0E.js";const m=JSON.parse('{"title":"Gmail 모듈 (기관관리자)","description":"","frontmatter":{},"headers":[],"relativePath":"04-org-admin-guide/modules-gmail.md","filePath":"04-org-admin-guide/modules-gmail.md","lastUpdated":1780579853000}'),l={name:"04-org-admin-guide/modules-gmail.md"};function r(i,t,h,n,s,u){return e(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="gmail-모듈-기관관리자" tabindex="-1">Gmail 모듈 (기관관리자) <a class="header-anchor" href="#gmail-모듈-기관관리자" aria-label="Permalink to &quot;Gmail 모듈 (기관관리자)&quot;">​</a></h1><p>기관 구성원 각자가 본인의 Gmail 을 워크허브 화면에서 다루고, Claude MCP 스킬로 메일을 자동 분류할 수 있도록 Gmail 모듈을 활성화합니다.</p><blockquote><p><strong>사용자 흐름은 본인 단위</strong>: Gmail 모듈은 기관 단위로 활성화되지만, 실제 OAuth 동의와 메일 접근은 <strong>각 사용자가 본인 Google 계정 단위로</strong> 진행합니다. 기관관리자는 모듈을 켜고 운영을 모니터링하며, 본인이 다른 사용자의 메일함은 절대 볼 수 없습니다.</p></blockquote><hr><h2 id="_1-사전-조건" tabindex="-1">1. 사전 조건 <a class="header-anchor" href="#_1-사전-조건" aria-label="Permalink to &quot;1. 사전 조건&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>확인 위치</th></tr></thead><tbody><tr><td>Google 모듈 활성화 (Workspace OAuth Client 등록)</td><td><a href="./google-integration.html">구글 드라이브/메일 연동</a> 참고</td></tr><tr><td>GCP 프로젝트에서 <strong>Gmail API</strong> 활성화</td><td>Google Cloud Console → API 라이브러리</td></tr><tr><td>OAuth 동의 화면 scope 에 Gmail scope 추가</td><td>아래 2번 참고</td></tr></tbody></table><p>Google 모듈이 등록돼 있지 않으면 Gmail 모듈 토글은 disabled 상태로 표시됩니다.</p><hr><h2 id="_2-oauth-scope-gmail" tabindex="-1">2. OAuth Scope (Gmail) <a class="header-anchor" href="#_2-oauth-scope-gmail" aria-label="Permalink to &quot;2. OAuth Scope (Gmail)&quot;">​</a></h2><p>Gmail 모듈은 다음 scope 를 요구합니다 — Google Cloud Console 의 OAuth 동의 화면에 모두 추가:</p><table tabindex="0"><thead><tr><th>Scope</th><th>용도</th><th>분류</th></tr></thead><tbody><tr><td><code>gmail.readonly</code></td><td>받은편지함 / 본문 조회</td><td><strong>restricted</strong></td></tr><tr><td><code>gmail.modify</code></td><td>Gmail 라벨 추가/제거, 읽음 표시</td><td>restricted</td></tr><tr><td><code>gmail.send</code></td><td>답장 / 새 메일 발신</td><td>sensitive</td></tr><tr><td><code>gmail.labels</code></td><td>라벨 트리 조회</td><td>sensitive</td></tr></tbody></table><blockquote><p><code>gmail.readonly</code> 는 Google 의 <strong>restricted scope</strong> 분류 — External 프로덕션으로 게시하려면 <strong>연간 보안평가(Annual Security Assessment, 유료)</strong> 가 필요합니다. 자세히는 <a href="./google-integration.html#_5-운영-모드-결정-internal-vs-external">구글 연동 — 운영 모드 결정</a> 참고.</p></blockquote><hr><h2 id="_3-모듈-활성화" tabindex="-1">3. 모듈 활성화 <a class="header-anchor" href="#_3-모듈-활성화" aria-label="Permalink to &quot;3. 모듈 활성화&quot;">​</a></h2><h3 id="_3-1-화면-이동" tabindex="-1">3.1 화면 이동 <a class="header-anchor" href="#_3-1-화면-이동" aria-label="Permalink to &quot;3.1 화면 이동&quot;">​</a></h3><p>좌측 사이드바 → <strong>관리자 → 모듈 관리</strong> (<code>/app/admin/modules</code>)</p><h3 id="_3-2-구글-메일-카드-토글-on" tabindex="-1">3.2 &quot;구글 메일&quot; 카드 토글 ON <a class="header-anchor" href="#_3-2-구글-메일-카드-토글-on" aria-label="Permalink to &quot;3.2 &quot;구글 메일&quot; 카드 토글 ON&quot;">​</a></h3><ul><li>사전조건 체크 — Google 모듈 활성 + GCP Gmail API 활성 모두 ✓ 표시되어야 토글 가능</li><li>토글 ON 즉시 좌측 사이드바에 <strong>&quot;메일&quot;</strong> 메뉴가 추가됨</li></ul><h3 id="_3-3-사용자-oauth-흐름" tabindex="-1">3.3 사용자 OAuth 흐름 <a class="header-anchor" href="#_3-3-사용자-oauth-흐름" aria-label="Permalink to &quot;3.3 사용자 OAuth 흐름&quot;">​</a></h3><p>각 사용자가 본인 화면에서 직접 진행:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>사용자 → 좌측 메뉴 [메일] → 상단 배너 [Google 계정 연결]</span></span>\n<span class="line"><span>       → 본인 Gmail 동의 화면 → &quot;허용&quot; → 본인 계정으로 OAuth 토큰 발급</span></span>\n<span class="line"><span>       → 2~5분 내 최근 200통 동기화 완료</span></span></code></pre></div><p>기관관리자는 이 흐름에 개입하지 않으며, 사용자 본인 계정의 메일만 본인 화면에 표시됩니다.</p><p>자세한 사용자 가이드: <a href="./../02-user-guide/gmail-module.html">Gmail 모듈 (사용자 가이드)</a></p><hr><h2 id="_4-watch-push-구독-자동-갱신" tabindex="-1">4. Watch / Push 구독 자동 갱신 <a class="header-anchor" href="#_4-watch-push-구독-자동-갱신" aria-label="Permalink to &quot;4. Watch / Push 구독 자동 갱신&quot;">​</a></h2><p>새 메일 도착 시 실시간 동기화를 위해 워크허브는 Gmail Watch API 로 push 구독을 등록합니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>동작</th></tr></thead><tbody><tr><td>Watch 등록</td><td>사용자 첫 OAuth 동의 시 자동 등록 (Pub/Sub 토픽 경유)</td></tr><tr><td>Watch 만료</td><td>Gmail 측 정책: 7일마다 만료</td></tr><tr><td>자동 갱신</td><td>워크허브 시스템 cron 이 매일 새벽 갱신 — <strong>기관관리자 조치 불필요</strong></td></tr><tr><td>Pub/Sub 토픽 환경변수</td><td>시스템 환경변수 <code>GMAIL_PUSH_TOPIC</code> (시스템관리자 영역)</td></tr></tbody></table><p>push 가 일시 끊겨도 매일 새벽 history sync 가 누락분을 채워줍니다.</p><hr><h2 id="_5-데이터-최소화-—-30일-본문-캐시-ttl" tabindex="-1">5. 데이터 최소화 — 30일 본문 캐시 TTL <a class="header-anchor" href="#_5-데이터-최소화-—-30일-본문-캐시-ttl" aria-label="Permalink to &quot;5. 데이터 최소화 — 30일 본문 캐시 TTL&quot;">​</a></h2><table tabindex="0"><thead><tr><th>데이터</th><th>보관 정책</th></tr></thead><tbody><tr><td><strong>메일 본문</strong> (<code>body_cached</code>)</td><td>워크허브 DB 에 30일만 캐시. 매일 새벽 cron 이 30일 초과분 자동 삭제</td></tr><tr><td>메일 메타 (제목·보낸이·라벨)</td><td>영구 보관 — 검색/필터에 사용</td></tr><tr><td>워크허브 태그 / 처리완료 상태</td><td>영구 보관 — 본인 부가 정보</td></tr><tr><td>OAuth refresh token</td><td>AES-256-GCM 으로 암호화 후 보관</td></tr></tbody></table><p>본문은 다시 보면 Gmail API 에서 즉시 재인출해서 캐시 — 사용자 입장에서는 차이를 느끼지 않습니다.</p><hr><h2 id="_6-모듈-비활성화-시-영향" tabindex="-1">6. 모듈 비활성화 시 영향 <a class="header-anchor" href="#_6-모듈-비활성화-시-영향" aria-label="Permalink to &quot;6. 모듈 비활성화 시 영향&quot;">​</a></h2><p>기관관리자가 Gmail 모듈 토글 OFF 시:</p><table tabindex="0"><thead><tr><th>항목</th><th>영향</th></tr></thead><tbody><tr><td>좌측 사이드바 &quot;메일&quot; 메뉴</td><td>즉시 사라짐</td></tr><tr><td>기존 메일 동기화 (push / cron)</td><td>즉시 중단</td></tr><tr><td>사용자 OAuth 토큰</td><td>DB 에 보관됨 (재활성 시 즉시 복구)</td></tr><tr><td>메일 메타 / 태그 / 처리완료 상태</td><td>보관됨 (재활성 시 복구)</td></tr><tr><td>메일 본문 캐시</td><td>TTL 정책대로 자연 만료</td></tr><tr><td>MCP 도구 <code>gmail_*</code></td><td>모듈 비활성으로 호출 시 403</td></tr></tbody></table><p>완전 삭제를 원하면 별도 데이터 정리 운영이 필요 — 시스템관리자에게 문의.</p><hr><h2 id="_7-트러블슈팅" tabindex="-1">7. 트러블슈팅 <a class="header-anchor" href="#_7-트러블슈팅" aria-label="Permalink to &quot;7. 트러블슈팅&quot;">​</a></h2><h3 id="사용자-화면에서-메일-메뉴가-안-보임" tabindex="-1">사용자 화면에서 &quot;메일&quot; 메뉴가 안 보임 <a class="header-anchor" href="#사용자-화면에서-메일-메뉴가-안-보임" aria-label="Permalink to &quot;사용자 화면에서 &quot;메일&quot; 메뉴가 안 보임&quot;">​</a></h3><p>체크:</p><ol><li>Google 모듈 활성 + Gmail 모듈 활성 모두 ON</li><li>(구버전 권한 정책) 메일 모듈에 PolicyAllowlist 가 설정돼 있으면 명시적으로 추가된 사용자만 접근</li></ol><h3 id="새-메일이-push-로-안-들어옴" tabindex="-1">새 메일이 push 로 안 들어옴 <a class="header-anchor" href="#새-메일이-push-로-안-들어옴" aria-label="Permalink to &quot;새 메일이 push 로 안 들어옴&quot;">​</a></h3><ul><li>Pub/Sub 토픽 환경변수 (<code>GMAIL_PUSH_TOPIC</code>) 미설정 — 시스템관리자 문의</li><li>watch 만료 — 매일 새벽 cron 이 자동 갱신하지만, 즉시 복구 원하면 사용자가 메일 화면 [새로고침]</li><li>사용자 Gmail 필터가 INBOX 라벨을 제거하는 경우 — 해당 메일은 push 대상에서 빠짐 (cron 사후 보충)</li></ul><h3 id="사용자-토큰-만료-권한-회수" tabindex="-1">사용자 토큰 만료 / 권한 회수 <a class="header-anchor" href="#사용자-토큰-만료-권한-회수" aria-label="Permalink to &quot;사용자 토큰 만료 / 권한 회수&quot;">​</a></h3><ul><li>사용자 화면에 &quot;Google 연결 만료&quot; 배너 표시 → 사용자 본인이 재연결</li><li>기관관리자는 이 흐름에 개입 불필요</li></ul><h3 id="발신-gmail-send-시-412-precondition-required" tabindex="-1">발신 (<code>gmail.send</code>) 시 &quot;412 Precondition Required&quot; <a class="header-anchor" href="#발신-gmail-send-시-412-precondition-required" aria-label="Permalink to &quot;발신 (`gmail.send`) 시 &quot;412 Precondition Required&quot;&quot;">​</a></h3><ul><li>OAuth 동의 시점에 <code>gmail.send</code> scope 가 빠진 경우</li><li>사용자가 <a href="https://myaccount.google.com/permissions" target="_blank" rel="noreferrer">https://myaccount.google.com/permissions</a> 에서 워크허브 권한 회수 후 재연결</li></ul><hr><h2 id="_8-보안-권장사항" tabindex="-1">8. 보안 권장사항 <a class="header-anchor" href="#_8-보안-권장사항" aria-label="Permalink to &quot;8. 보안 권장사항&quot;">​</a></h2><ul><li><strong>OAuth refresh token</strong> 은 AES-256-GCM 으로 암호화 저장 — DB 덤프 유출 시에도 토큰 보호</li><li><strong>본문 캐시 30일 TTL</strong> — 장기 보관 데이터 최소화 원칙 준수</li><li>기관관리자는 다른 사용자의 메일 내용을 볼 수 없음 (DB 접근 권한이 있어도 평문 본문은 cron 으로 삭제 + scope 무관)</li><li>본인이 회사 퇴사 시 본인이 직접 권한 회수 권장 (<code>myaccount.google.com/permissions</code>)</li></ul><hr><h2 id="관련-가이드" tabindex="-1">관련 가이드 <a class="header-anchor" href="#관련-가이드" aria-label="Permalink to &quot;관련 가이드&quot;">​</a></h2><ul><li><a href="./google-integration.html">구글 드라이브/메일 연동</a> — Google OAuth Client 등록 (사전 조건)</li><li><a href="./../02-user-guide/gmail-module.html">Gmail 모듈 (사용자 가이드)</a> — 사용자 화면 / Claude MCP 트리아지 스킬</li><li><a href="./modules-gdrive.html">Drive 모듈 (관리자)</a> — Gmail 첨부 → Drive 저장 흐름</li><li><a href="./modules-mcp.html">MCP 모듈 (관리자)</a> — Gmail MCP 도구 노출 정책</li></ul>',54)])])}const p=a(l,[["render",r]]);export{m as __pageData,p as default};
